document.title='Wokaya Thoughtful websites. Better business.';const favicon=document.querySelector('link[rel="icon"]');if(favicon)favicon.href='assets/wokaya-logo.png';
document.querySelectorAll('.brand').forEach(brand=>{brand.textContent='';const logo=document.createElement('img');logo.className='brand-logo';logo.src='assets/wokaya-logo.png';logo.alt='Wokaya logo';brand.append(logo)});
const serviceIcons=[`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 8h12l1 12H5L6 8Z"/><path d="M9 8a3 3 0 0 1 6 0"/></svg>`,`<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 8h18M8 12h8M8 16h5"/></svg>`,`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 17 5-5 4 3 7-8"/><path d="M15 7h5v5"/></svg>`];document.querySelectorAll('.service-symbol').forEach((symbol,index)=>{symbol.textContent='';symbol.innerHTML=serviceIcons[index]});
const wordpressService=[...document.querySelectorAll('.service')].find(service=>service.textContent.includes('WordPress websites'));const wordpressCta=wordpressService?.querySelector('a');if(wordpressCta)wordpressCta.href='https://www.fiverr.com/wokaya/increase-shopify-store-website-speed-seo-and-optimization?ref_ctx_id=804544dac18c4110940b8162ee550a69&pckg_id=1&source=seller_page';
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;
reduced.addEventListener('change',()=>{paused=reduced.matches;document.documentElement.classList.toggle('motion-paused',paused)});document.documentElement.classList.toggle('motion-paused',paused);
if(!reduced.matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}},{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
const stage=document.querySelector('.project-stage');let progress=0,frameId=0;
function renderStage(){frameId=0;if(paused||innerWidth<801){stage.style.transform='';return}const r=document.querySelector('.hero').getBoundingClientRect();progress=Math.max(0,Math.min(1,-r.top/r.height));stage.style.transform=`translateY(${progress*-45}px)`}
addEventListener('scroll',()=>{if(!frameId)frameId=requestAnimationFrame(renderStage)},{passive:true});addEventListener('resize',renderStage);
document.querySelectorAll('.questions details').forEach(detail=>detail.addEventListener('toggle',()=>{if(detail.open)document.querySelectorAll('.questions details').forEach(other=>{if(other!==detail)other.open=false})}));
const archiveCards=[...document.querySelectorAll('.archive-card')],archiveFilters=[...document.querySelectorAll('[data-filter]')],projectSearch=document.querySelector('#project-search'),moreWrap=document.querySelector('.archive-more'),moreButton=document.querySelector('#show-projects'),emptyState=document.querySelector('.archive-empty');let projectFilter='All',projectsExpanded=false;
function filterProjects(){const query=projectSearch.value.trim().toLowerCase();const matched=archiveCards.filter(card=>(projectFilter==='All'||card.dataset.platforms.split(' ').includes(projectFilter))&&card.dataset.search.includes(query));const limit=projectsExpanded?matched.length:12;archiveCards.forEach(card=>card.hidden=true);matched.slice(0,limit).forEach(card=>card.hidden=false);document.querySelector('#archive-status').textContent=`Showing ${Math.min(limit,matched.length)} of ${matched.length} ${projectFilter==='All'?'':projectFilter+' '}projects`;emptyState.hidden=matched.length>0;moreWrap.hidden=matched.length<=12;moreButton.innerHTML=projectsExpanded?'Show fewer projects <span>↑</span>':`Show all ${matched.length} projects <span>↓</span>`;archiveFilters.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.filter===projectFilter)));}
archiveFilters.forEach(button=>button.addEventListener('click',()=>{projectFilter=button.dataset.filter;projectsExpanded=false;filterProjects()}));projectSearch.addEventListener('input',()=>{projectsExpanded=false;filterProjects()});moreButton.addEventListener('click',()=>{projectsExpanded=!projectsExpanded;filterProjects();if(!projectsExpanded)document.querySelector('#portfolio').scrollIntoView({behavior:paused?'instant':'smooth',block:'start'})});document.querySelector('#reset-projects').addEventListener('click',()=>{projectFilter='All';projectsExpanded=false;projectSearch.value='';filterProjects();projectSearch.focus()});filterProjects();
